criteria.command:
rm -f .task/netsim/results/5-s*-r*.json; NETSIM_SCENARIOS=5 NETSIM_SEEDS='1 2 3' NETSIM_REPEAT=10 NETSIM_EXPECT=strict mise run e2e:netsim:impaired && python3 -I -c "import json,sys; bad=[]; n=0
for s in (1,2,3):
 for r in range(1,11):
  f=f'.task/netsim/results/5-s{s}-r{r}.json'
  try: c={x['id']:x for x in json.load(open(f))['clauses']}
  except OSError: bad.append((f,'missing')); continue
  n+=1; bad+=[(f,k) for k,v in c.items() if v['status']!='pass']
  if 'level' not in c.get('C5',{}).get('bound',''): bad.append((f,'C5 is not the level rule'))
sys.exit(f'e2e-C5: {n}/30 runs, {bad[:6]}' if bad or n!=30 else 0)"
